"""Hand-authored articles, stored DRAFT. This script never sets indexability."""
import json
from pathlib import Path
from datetime import date

from pathlib import Path as _GenerationPath
import json as _generation_json
_control = _GenerationPath(__file__).resolve().parents[1] / "content/editorial/generation-control.json"
if _control.exists() and _generation_json.loads(_control.read_text()).get("status") == "PAUSED_FOR_LAUNCH":
    raise SystemExit("Content generation is PAUSED_FOR_LAUNCH. Resume only after an explicit user instruction.")

briefs=json.loads(Path('content/editorial/first-500-inventory.json').read_text())
articles=[]
def article(topic,title,description,intro,sections,example,sources):
 brief=next(row for row in briefs if row['path']==topic)
 body={**brief,'title':title,'h1':title,'description':description,'canonical':topic,'status':'DRAFT','indexable':False,'intro':intro,'sections':[{'heading':heading,'paragraphs':paragraphs} for heading,paragraphs in sections],'example':example,'faq':[],'related':[],'sources':[{'title':name,'url':url} for name,url in sources],'lastUpdated':str(date.today()),'review':{'accuracy':True,'distinctValue':True,'answerFirst':True,'supportedClaims':True,'examples':True,'specificity':True,'reviewer':'Project implementation review','reviewedAt':str(date.today())}}
 articles.append(body)
ff=[('FFmpeg stream mapping and metadata','https://www.ffmpeg.org/ffmpeg.html'),('FFprobe stream inspection','https://ffmpeg.org/ffprobe.html')]
yt=[('yt-dlp format selection','https://github.com/yt-dlp/yt-dlp#format-selection')]
article('/guides/general/video-container-vs-codec/','Video container versus codec: diagnose the right layer','Learn why MP4, WebM and MKV identify containers, while H.264, AAC and Opus identify streams, and use that distinction to diagnose playback.',
'A filename ending in MP4 identifies a container, not a complete promise of playback compatibility. The container holds video, audio and metadata; codecs describe how each stream is encoded. Check both layers before choosing a player or concluding that a downloaded file is damaged.',[
('Read the file as a collection of streams',[
'A single local media file can hold one video stream and several audio streams. Those streams need not use the same codec, and the container does not turn them into one common encoding. H.264 video with AAC audio in MP4 is one combination; H.264 with AAC and Opus audio may require a different container in this downloader.',
'The quality selector concerns the selected source video. It is separate from the choice of an audio track and from the packaging decision. A container name therefore cannot tell you whether the file has the requested language, whether two languages are present, or whether the image is high resolution.']),
('Inspect before converting',[
'For a technical check, run ffprobe -v error -show_streams -of json against your own local file. Read codec_type to distinguish video from audio and codec_name for the encoding. The tags object may identify a stream language, while disposition indicates which track a player is expected to select by default.',
'Inspecting is a read-only operation. Converting requires a separate decision: changing containers by copying streams can preserve encoded packets, whereas transcoding decodes and encodes them again. This service chooses a compatible container for its selected source streams; it is not a general conversion editor.']),
('Troubleshoot a file that will not play',[
'If the filename and duration look reasonable but a player reports an unsupported format, identify the unsupported stream. An application might understand the container and video while lacking the audio decoder. Another application can be tried on a file you are entitled to play without pretending its bytes have changed.',
'Do not rename an MKV extension to MP4 as a repair. That changes the label, not its container structure or codecs. Retain the original file while diagnosing; if an actual conversion is needed, make a separate copy and check duration, sound and image after conversion.'])],
'A selected source has H.264 video plus English AAC and Hindi Opus audio. A file named clip-dual-audio.mkv can preserve that combination. Calling it MP4 without changing its structure would not give an MP4-only player an Opus decoder. Inspect all three streams, then choose a player that supports the actual file.',ff)
article('/guides/general/dual-audio-vs-stereo/','Dual audio versus stereo: tracks are not channels','Distinguish two selectable language streams from left and right stereo channels, and verify a dual-audio file without mixing languages.',
'Dual audio means two separate selectable audio streams in one video file. Stereo usually means two channels within one audio stream. Placing English in the left channel and Hindi in the right channel is not the same result as two independent language tracks that a player can switch between.',[
('Count streams first, channels second',[
'A stereo English track can contain left and right channels while remaining one language stream. A dual-audio video can contain two mono tracks, two stereo tracks, or another supported channel arrangement. The channel layout of an individual track does not determine how many language choices the file contains.',
'The downloader’s Dual Audio mode maps the selected primary and secondary source tracks separately. It copies their encoded audio where a compatible container is possible. It does not synthesize a second language, pan two voices into left and right speakers, or claim that changing a device language creates translated audio.']),
('Verify the downloaded file',[
'Inspect the local output with FFprobe and count entries whose codec_type is audio. The expected dual result has two such entries and one video entry. A channels value of 2 on only one audio entry confirms stereo channels, not two language streams.',
'Language tags help identify which stream is English or Hindi when source metadata genuinely identifies them. Missing language metadata remains unknown. The primary selection is written as the default track so compatible players have an initial choice; the secondary stays separately selectable.']),
('Troubleshoot hearing both languages or only one',[
'Hearing only the primary language in a web preview does not prove the second track is absent. Browser previews may expose only one stream even when the local container contains both. Use a downloaded-file player with audio-track selection and inspect the stream inventory if the control is unclear.',
'If both languages are audibly mixed at the same time, determine whether the source itself supplied a mixed recording. A stream copier cannot reliably unmix voices that already share one encoded stream. Keep the source file and choose a different genuine source track if one is available; do not relabel a mixture as separate languages.'])],
'An inspection shows one H.264 stream followed by two AAC streams, each with channels set to 2. This is one video with two stereo audio tracks. A different inspection showing one AAC stream with two channels is ordinary stereo even if both languages happen to be audible within it.',ff)
article('/guides/general/missing-source-language/','Why an available audio stream may have no language label','Understand unknown source language metadata, the Original fallback label, and why subtitles or browser preferences cannot supply missing audio evidence.',
'An audio stream can be real and playable without a reliable language tag. When the source does not identify its language, this downloader keeps that language unknown. A compact Original label for a sole track is a user-interface fallback; it is not evidence that the engine detected English or any other language.',[
('Separate existence from identification',[
'A codec and stream index can establish that audio exists. They do not identify the language spoken in it. Source language tags and extractor metadata supply a different kind of evidence, and they are sometimes absent even on ordinary videos with sound.',
'The normalization layer considers audio-bearing formats and measured embedded streams. It does not create extra tracks from a subtitles menu, from the browser interface language, or from a general description of the video. Several bitrate versions of the same track should not appear as several languages.']),
('Read the available control honestly',[
'With one unknown audio option, a small Audio: Original summary avoids presenting a made-up language picker. That is different from source-confirmed original/default flags. Where source metadata marks a known track as original or default, those roles can be shown explicitly alongside its language.',
'A larger language selector appears only when real compatible source options exist. Selecting a video quality can change which audio options can be packaged with it. Recheck the selection after changing quality rather than assuming a language remains available for every format.']),
('Check a mismatch without guessing',[
'An exported stream may use und, meaning undefined language, rather than an invented language code. That is not the same as silent audio. Play the file to establish whether sound is present, and inspect the stream list if a player hides its controls.',
'If a source explicitly identifies a selected language but the downloaded stream carries contradictory language metadata, the engine rejects that conflict before writing the desired label onto the output. This check prevents a wrong stream from appearing verified merely because it was renamed. Unknown metadata is preserved rather than filled with a guess.'])],
'The live ordinary YouTube regression for Me at the zoo produced one real AAC stream whose language tag stayed und. Its source offered no reliable language label in that extraction. Calling the option English would have invented metadata; labeling the single choice Original kept the workflow usable while leaving its language unknown.',yt+ff)
article('/guides/general/original-vs-default-audio/','Original versus default audio: choose the intended role','Learn why a source’s original audio, its preferred default track, and the primary track in a downloaded file can differ.',
'Original and default describe different roles. Original identifies the source’s original audio when the provider supplies that evidence. Default describes a preferred initial selection. Your primary downloaded track can become the output default without changing which source track was original or creating a translation.',[
('Interpret source roles separately',[
'A multilingual source might mark its creator’s original track as English but prefer a dubbed language for a particular source response. The extractor can expose language, original and default flags independently. Treat each as metadata about the observed source, not a permanent provider-wide rule.',
'An audio-description track is also a separate role. It may share the main track’s language but carry additional narration. The normalized inventory keeps relevant role evidence while avoiding duplicate bitrate options masquerading as new languages. Unknown roles are not inferred from a user’s preferred language.']),
('Choose primary and secondary intentionally',[
'In Single Audio mode, select the one source option you want to hear. In Dual Audio mode, choose the intended starting language as primary and a genuinely different language as secondary when compatible options are available. The primary is the output’s default audio disposition.',
'The output keeps source-role information distinct from its final default flag. A source-default track chosen as secondary should not still be labeled as the output default. The ready-file summary reflects the inspected output so the displayed default agrees with the actual file.']),
('Troubleshoot a player starting with the wrong track',[
'A player may retain a saved language preference or offer its own track choice. Inspect the file’s default disposition and the available audio streams before treating unexpected playback as a failed download. Try the audio selection control in a compatible local player.',
'If the source supplies only one track or no language metadata, the service cannot promise an original-language alternative. Source-driven selection is not dubbing. Live multilingual extraction has been observed, but the project’s full live dual-audio attempts reached the processing limit; the local mux tests do not imply every multilingual source will finish successfully.'])],
'Choose Hindi as primary and English as secondary from an actual compatible source. The final file should identify Hindi as default, with English separately selectable. English may retain a source-original role. Those two facts are consistent: default playback is your output preference, while original is a source characteristic.',yt+ff)
article('/guides/general/subtitle-language-vs-audio-language/','Subtitle language versus audio language: what changes the sound?','Separate text translation from source audio streams and understand why a subtitles menu cannot create downloadable language tracks.',
'Subtitles are text or timed captions; audio tracks carry sound. A video offering Hindi subtitles does not necessarily offer Hindi speech. The audio selector therefore uses audio-bearing source formats, not the caption list, and it cannot translate or dub an English-only recording.',[
('Check the right source evidence',[
'A platform can expose several subtitle languages while its actual video has only one audio stream. Captions may also describe sounds, transcribe the original language, or provide translated text. None of those categories proves a second encoded audio track exists.',
'For this downloader, genuine audio choices need compatible source streams or measured embedded audio streams. Language metadata is read from those streams or their extractor records. A top-level text hint about the video’s language is not a substitute for a specific audio option.']),
('Distinguish selection from generation',[
'Choosing an existing Hindi track selects supplied speech. Dubbing would create or transform speech, which this product does not offer. Its multiple-audio feature maps selected tracks into one file, preserving separate streams rather than generating voices.',
'Similarly, putting a subtitles file beside a video does not alter its audio codec or spoken language. A compatible player may display text while still playing the original audio. Do not describe that combination as a Hindi-audio download if the actual sound remains English.']),
('Troubleshoot an absent language option',[
'Check whether the platform’s own audio control lists the language separately from captions. Even then, anonymous source access and the selected quality can affect what the extractor can actually obtain. The service only displays compatible options returned for this particular analysis.',
'If the expected language is absent, do not paste credentials or modify an internal track identifier to force it. Recheck the same public source if availability has changed, or request the owner’s authorized file. A known subtitles menu should not be converted into an unsupported audio promise.'])],
'A source exposes English AAC audio and Hindi subtitles. The audio inventory correctly contains only English; there is no Hindi audio selection to mux. A different source exposing separate English and Hindi audio streams can offer those two languages, even if its subtitles inventory is entirely empty.',yt+ff)
article('/guides/general/temporary-analysis-session/','Why a video analysis session expires before preparation','Understand the ten-minute analysis window, stale format selections, and the correct way to refresh a source without reusing old identifiers.',
'An analysis session is temporary evidence about one source response. In the current configuration it expires after ten minutes. If preparation says the session is unavailable or expired, analyze the public link again and choose from the new inventory; do not reuse old format or audio identifiers.',[
('What a session remembers',[
'The backend associates the submitted source with actual available formats and session-bound audio choices. The browser receives opaque identifiers that refer to those stored selections. They are not universal format codes that can be copied from another clip or reconstructed from a filename.',
'Source media URLs, headers and available formats can change while a page is open. Keeping sessions bounded reduces reliance on stale source information. Session expiration is separate from a later prepared file’s expiration, which concerns the temporary output and its download token.']),
('Refresh the complete choice',[
'Paste the same authorized public source URL and run the check again. When metadata returns, inspect quality, container and audio options before starting preparation. The same clip may present a different usable inventory because the source response changed.',
'If you change quality, also check that your audio selection still belongs to that quality’s compatible choices. A session-bound ID from the previous analysis is not valid evidence for the new session, even if its visible label looks identical. Let the interface create the new request.']),
('Troubleshoot repeated expiration',[
'Prepare after selecting your formats rather than leaving an analysis idle for a long period. If it expires immediately after a fresh check, retain the error category and timing for diagnosis without posting temporary source URLs or private credentials.',
'A repeated session failure can also occur when a browser tab sends an old request after the link has been cleared or replaced. The current interface guards against stale extraction responses replacing a newer choice. Reloading a session should reset ready-file state instead of suggesting the previous file belongs to a new source.'])],
'At 12:00, a check returns session A with 360p and an English audio option. At 12:15, its stored selection has expired. A new analysis produces session B. Even if 360p and English still appear, select them from B; sending A’s audio ID with B must be rejected rather than mapped to an arbitrary stream.',yt)
article('/guides/general/local-file-vs-expired-link/','A local video file is different from an expiring download link','Separate temporary analysis and file tokens from media bytes saved on your device, and know when to reprepare an expired output.',
'A prepared download link is temporary; a completed local file is a separate copy on your device. When the service link expires, it does not remotely delete a file you already saved. A bookmarked token URL, however, is not a durable archive of the video.',[
('Understand the three locations',[
'The source platform owns the upstream media and controls its access. The service temporarily prepares an output for your selection. The browser then transfers that output to a local or chosen cloud-backed folder. These locations have different lifetimes and permissions.',
'In the current project configuration, analysis sessions and output links expire after ten minutes, and temporary output cleanup is periodic. This is operational storage, not a permanent video hosting library. The browser must finish saving before the service link ceases to be usable.']),
('Verify that a copy really exists',[
'Use your browser’s download history to find a completed entry, then reveal the saved file in its destination folder. Check that its size is greater than zero and its duration and audio match your selected output. Merely opening a preview or bookmarking its URL does not perform this check.',
'When the destination is a synced cloud folder, distinguish the local file from a cloud placeholder. Make sure it is actually available on the device before relying on offline playback. The service cannot guarantee a separate storage provider’s sync or retention behavior.']),
('Troubleshoot an expired token',[
'If you have not retained a completed file, return to the original authorized public media link and analyze it again. The upstream content may have changed or disappeared, so a fresh successful extraction is required. Reusing an old token does not extend its validity.',
'If the local file is damaged or incomplete, preserve the error information and obtain a new output when the source remains accessible. Do not treat an HTML error response saved with a video extension as a valid archive. Keep source attribution separately from the temporary service token if you need future context.'])],
'A browser successfully saves clip-360p.mp4 into Downloads at 12:05. At 12:20 the service token no longer works, but the saved file still opens locally. In contrast, a bookmark containing only the service URL cannot recreate the file after expiry; it points to temporary storage rather than an owned archive.',yt)
article('/guides/general/opaque-format-identifiers/','Why format and audio identifiers belong to one analysis','Understand opaque session IDs, safe format selection, and why copying track IDs between videos cannot create missing language support.',
'Format and audio identifiers are server-issued selections tied to a particular analysis. They are not source URLs, language names or commands. Use the choices returned by the current session; supplying another video’s identifier cannot unlock a format or language absent from the source.',[
('A label is not the stream itself',[
'Two separate videos may both display 360p or English, but the backend stores different source URLs and stream indexes for them. A friendly label describes a selection; its opaque ID identifies a stored option. The association matters when selecting multiple audio tracks.',
'The source-facing format information remains behind the normalized provider interface. Public tool pages all use that interface rather than maintaining separate extraction logic. It prevents a frontend page from constructing an arbitrary provider command or selecting a stream that was never analyzed.']),
('What the request is allowed to select',[
'A download request identifies the session, a returned format, an audio mode and the selected audio-track IDs. Single mode needs one valid track when an audio inventory exists. Dual mode needs two compatible distinct-language choices; duplicate IDs and duplicate known-language choices are rejected.',
'The backend resolves the stored IDs to local input planning, applies its existing network safeguards, and explicitly maps selected audio indexes. The browser does not submit a raw ffmpeg argument or an upstream media URL as a substitute for a reviewed selection.']),
('Troubleshoot unavailable selections',[
'A track-unavailable response can mean the session has expired, the source has changed, or the chosen audio is incompatible with the selected quality. Run a fresh check and choose its returned options. Switching quality may require a different audio choice or a return to Single Audio mode.',
'Do not edit an ID to resemble a language code or copy one from a different tab. Such changes should fail rather than silently select default audio. A truthful failure is preferable to a file mislabeled as the requested language. No ID manipulation provides access to private content or creates translated speech.'])],
'Session A offers English track audio-1; session B offers a different source with an opaque identifier that happens to be similarly named. A request referencing B must use B’s returned inventory. Combining A’s selection with B’s session is invalid even though both sources visibly claim the same language.',yt)
article('/guides/general/verified-file-readiness/','What Ready means before a video file can be downloaded','Learn the difference between a queued request and a verified output, including stream-count, size and language checks before file delivery.',
'Ready means preparation finished and the output passed the downloader’s final inspection. A queued or processing response is not a successful download. The service must have an actual file before it can report its exact output size or offer a verified save link.',[
('Follow preparation through its states',[
'After a valid selection, the API can accept a preparation job without immediately returning media bytes. The interface polls the job for progress. Source fetching and any required stream merge must finish before the final file state is available.',
'A source response can provide estimated size or dimensions during analysis, but that is distinct from the output file. Remuxing and a different audio selection can change final bytes. Exact prepared-file size therefore comes from the file, not a hard-coded quality table or an assumed bitrate.']),
('Inspect the completed output',[
'Before readiness, FFprobe validates video dimensions, duration and stream inventory. The expected result contains one video stream and the selected number of audio streams. Known selected language tags and unchanged audio codecs are checked, with default disposition applied to the primary track in multiple-audio output.',
'The engine also inspects selected local input streams before muxing. Explicitly contradictory source language metadata is rejected rather than overwritten with the requested label. These checks verify the packaging and selection evidence; they do not infer the spoken language when the source metadata is unknown.']),
('Troubleshoot preparation that never becomes ready',[
'Processing is bounded by duration, file size and timeout settings. A job can fail when the source is unavailable or the output cannot be verified. A timeout must not leave an offered fake success file. Failure cleanup removes temporary preparation output.',
'The same public link may offer a smaller compatible format that fits the limits, but the interface must show that real source option first. Do not describe a partial clip or a relabeled HTML response as the requested full video. If no supported choice succeeds, obtain an authorized original from its owner instead.'])],
'A dual-audio request is accepted as queued. The engine fetches its inputs and creates an output, but inspection finds only one audio stream instead of two. That job fails verification; the existence of some bytes on disk is not enough to mark it ready or label it a successful dual-audio download.',ff)
article('/guides/general/source-provided-format-inventory/','Why available video qualities differ between source links','Use source-returned dimensions and formats to choose quality without assuming every clip offers HD, 4K or the same audio tracks.',
'Available qualities come from the actual source response for the submitted clip. A 4K label cannot be offered just because the platform supports 4K elsewhere. Compare the returned dimensions, compatible audio and container options for this one source before choosing a download.',[
('Read a quality option as evidence',[
'A format record can include width, height, codecs and an actual or estimated source size. Those values describe a supplied stream, not the original camera recording. The service filters unsupported or unusable formats instead of inventing a ladder of resolutions.',
'Portrait videos complicate familiar quality labels: the horizontal dimension can be the short side while the vertical dimension is larger. Read both dimensions where available. A tall video is not automatically a higher-detail version of the same landscape resolution label.']),
('Recheck audio compatibility for each quality',[
'Video and audio can arrive together or as separate formats. A selected video might have more than one compatible source audio choice, or only one. Packaging the actual codecs can result in MP4, WebM or MKV; the output container is part of the selection plan rather than a universal promise.',
'When a quality change removes an available secondary track, the interface resets the incompatible dual selection. This avoids requesting a combination the source did not supply. A language option seen on one format should not be assumed available on every other format.']),
('Troubleshoot missing high resolution',[
'The upstream upload may not supply higher resolution, the response may expose fewer variants, or authentication restrictions may limit available media. A fresh extraction can discover changed availability, but changing a label cannot create missing pixels. This service does not upscale a lower-resolution source and call it genuine 4K.',
'Choose a returned option that fits your playback and transfer needs. If a source offers no usable video format, retain the failure category and seek an authorized original file. Do not guess an upstream format ID from a different source or reuse an expired analysis to force a missing quality.'])],
'One public clip returns 640×360 and 1280×720 formats. Another returns only 640×360. The second tool should show 360p rather than a fake 720p or 4K button. Even the first source’s larger image does not by itself prove a larger audio-language inventory; inspect the compatible audio for the chosen format.',yt)
article('/guides/general/iphone-files-vs-photos/','An iPhone video in Files is not automatically in Photos','Find a completed browser download in Files, distinguish it from the Photos library, and verify a supported local video before importing.',
'A browser-downloaded video may be stored in Files without appearing in Photos. Check the actual download destination first; the Photos library is a separate collection. A successful file transfer does not promise that iOS can import or preview every container and codec combination.',[
('Locate the completed download',[
'Apple identifies the Downloads folder in Files as the place to find files downloaded from the internet. Open Files and look in the relevant storage location rather than assuming the item entered the camera roll. Safari’s download indicator can help locate a recent saved item.',
'Confirm the browser completed the transfer and identify the actual filename. The prepared filename may contain the selected resolution and audio-language or mode suffix. A temporary browser preview or a bookmark is not a saved local file, and the service’s expiring download link is not the same as the copy in Files.']),
('Check compatibility before moving libraries',[
'A file can be valid without having a container or codec combination supported by the destination library. MP4, WebM and MKV package streams differently, and the suffix alone does not reveal every codec inside. Multi-audio MKV should not be promised as a Photos-compatible import.',
'Use the available file preview or a suitable local player to verify duration and sound. If the share menu offers a supported save-to-library action, treat that as a separate import step. If the option is absent or fails, preserve the working file in Files instead of renaming its extension to force an import.']),
('Troubleshoot a missing item',[
'Check both the chosen local and cloud-backed Files locations when you are unsure where the browser stored it. A cloud placeholder may need retrieval before offline playback. The current service cannot guarantee another provider’s sync status or the device’s available storage.',
'If no completed file exists, reprepare the original authorized source while it remains accessible. Do not assume that keeping the preview tab open preserves an output after the service token expires. For future reuse, retain the completed file and its source context separately; do not store passwords or session cookies as part of a download workflow.'])],
'A downloaded MP4 appears in Files → Downloads and opens with sound, but Photos has no new video. That can simply mean it was never imported into Photos. A downloaded dual-audio MKV remaining in Files is also not evidence of failure; choose a compatible player rather than assuming every valid video belongs in the Photos library.',[('Apple: find downloads on iPhone or iPad','https://support.apple.com/en-ie/102440')]+ff)
article('/guides/general/browser-preview-vs-save/','Playing a browser preview does not save a permanent video','Distinguish streamed preview playback from an actual browser download, verify completed bytes, and avoid treating expiring preview links as archives.',
'Preview playback lets you inspect a video, but it does not prove a permanent copy exists in your download folder. Use the file-save action, wait for the transfer to complete, and verify the resulting local file. The preview URL can expire independently of a successfully retained copy.',[
('What the preview establishes',[
'A preview can help confirm that the analyzed clip is the one you intended and that the browser can play its available media. The browser may temporarily buffer bytes during playback, but buffering is not a user-controlled export with a durable filename and destination.',
'Preview support is also narrower than general file validity. Some valid containers are not previewable in the browser. A browser may play only the primary audio even when the downloaded file holds a separately selectable secondary track. Neither limitation should be hidden behind a fake playing video.']),
('Complete the separate save operation',[
'After preparation reaches Ready, use the offered save link and watch the browser’s download state. Identify its destination folder and verify that the completed file has nonzero size and plausible duration. Source formats and exact prepared output size should remain separate concepts.',
'Browser settings decide whether a transfer prompts for a destination or uses a default folder. Chrome documents its download workflow and destination behavior; other browsers have their own controls. Keep the original saved filename until playback has been checked so an extension change does not obscure what was delivered.']),
('Troubleshoot confusing success signals',[
'If a preview works but saving fails, record whether failure occurred during preparation or during the browser transfer. A ready file can still encounter device storage, browser or expired-link problems. Conversely, an unsupported preview does not prove a verified local MKV file is invalid.',
'If a saved item contains an error page rather than media, check its type and contents rather than trusting its extension. A token URL or browser tab is not a durable backup. Reanalyze the authorized source when a temporary link expires, and avoid repeating requests that bypass actual source access or file limits.'])],
'You can play a prepared clip in the web page at 12:05, but no entry appears in the browser’s completed downloads. At 12:20 its temporary link has expired. Because no permanent copy was saved, the earlier playback does not establish an archive; the source must be analyzed and prepared again if still accessible.',[('Chrome: download a file','https://support.google.com/chrome/answer/95759')])

# The first authored set owns cross-platform diagnostic intents, not keyword permutations.
for index,page in enumerate(articles):
 page['related']=[articles[(index+offset)%len(articles)]['path'] for offset in (1,2,3)]
existing=json.loads(Path('content/editorial/articles.json').read_text())
owned={page['path'] for page in articles}
articles += [page for page in existing if page['path'] not in owned]
Path('content/editorial/articles.json').write_text(json.dumps(articles,indent=2)+'\n')
print(f'Authored {len(articles)} DRAFT guides; no publication performed')
